// Normaliza o payload extraído para o formato único usado no restante do fluxo
const IGNORAR_CHAVES = ['messageContextInfo', 'senderKeyDistributionMessage'];
const POR_CHAVE = { audioMessage: 'audio', imageMessage: 'imagem', videoMessage: 'video', documentMessage: 'documento', documentWithCaptionMessage: 'documento',
  locationMessage: 'localizacao', liveLocationMessage: 'localizacao', contactMessage: 'contato', contactsArrayMessage: 'contato', stickerMessage: 'figurinha' };
const ROTULOS = { audio: 'áudio', imagem: 'imagem', video: 'vídeo', documento: 'documento', localizacao: 'localização', contato: 'contato' };
const COM_LEGENDA = ['imagem', 'video', 'documento'];
const soDigitos = (jid) => String(jid).split('@')[0].split(':')[0].replace(/\D/g, '');
return $input.all().map((item) => {
  const j = item.json;
  let tipo = 'ignorar';
  let texto = '';
  let legendaInterna = '';
  if (j.temDados) {
    const c = j.conteudo ?? {};
    const chave = Object.keys(c).find((k) => !IGNORAR_CHAVES.includes(k)) ?? '';
    if (chave === 'conversation' || chave === 'extendedTextMessage') {
      const interno = String(c.conversation ?? c.extendedTextMessage?.text ?? '').trim();
      if (interno) { tipo = 'texto'; texto = j.corpo || interno; }
    } else {
      tipo = POR_CHAVE[chave] ?? 'ignorar';
      legendaInterna = String(c[chave]?.caption ?? c.documentWithCaptionMessage?.message?.documentMessage?.caption ?? '');
    }
  } else if (!j.hasMedia) {
    if (j.corpo) { tipo = 'texto'; texto = j.corpo; }
  } else {
    // sem _data: decide pelo mimetype
    tipo = j.mimetype.startsWith('audio') ? 'audio' : j.mimetype.startsWith('image') ? 'imagem' : j.mimetype.startsWith('video') ? 'video' : 'documento';
  }
  const chatId = String(j.chatId ?? '');
  const alt = String(j.remoteJidAlt ?? '');
  const telefone = alt.endsWith('@s.whatsapp.net') ? soDigitos(alt)
    : (chatId.endsWith('@c.us') || chatId.endsWith('@s.whatsapp.net')) ? soDigitos(chatId) : '';
  return { json: {
    idMensagem: j.idMensagem, sessao: j.sessao, fromMe: j.fromMe, source: j.source, chatId,
    timestamp: j.timestamp, tipo, tipoLabel: ROTULOS[tipo] ?? '', texto,
    legenda: COM_LEGENDA.includes(tipo) ? (j.corpo || legendaInterna) : '',
    nomeContato: j.nomeContato, telefone, ehLid: chatId.endsWith('@lid'),
  } };
});

// Monta o texto do aviso ao grupo de atendimento (função pura, sem rede)
const h = $('7.3 Preparar handoff').first().json;
const cfg = $('CONFIG').first().json;
const tel = String(h.telefone ?? '').replace(/\D/g, '');
// 55 + DDD + 8 ou 9 dígitos vira +55 DD NNNN(N)-NNNN; outros países ficam só com +
const m = tel.match(/^55(\d{2})(\d{4,5})(\d{4})$/);
const telFmt = !tel ? '' : m ? `+55 ${m[1]} ${m[2]}-${m[3]}` : `+${tel}`;
const nome = String(h.nomeContato ?? '').trim() || 'sem nome';
const resumo = (Array.isArray(h.resumo) ? h.resumo : []).map((l) => String(l ?? '').trim()).filter(Boolean).slice(0, 3);
const ultimo = String(h.ultimoTexto ?? '').trim();
const linhas = ['Atendimento humano necessário', `Cliente: ${nome}${telFmt ? ' — ' + telFmt : ''}`];
// link só quando habilitado na CONFIG e houver telefone (chat @lid sem alt não tem)
if (cfg.INCLUIR_LINK_WA && tel) linhas.push(`Conversa: https://wa.me/${tel}`);
linhas.push(`Motivo: ${h.motivo ?? ''}`);
if (resumo.length) linhas.push('Resumo:', ...resumo.map((l) => `• ${l}`));
if (ultimo) linhas.push(`Última mensagem: "${ultimo}"`);
linhas.push(`O bot parou de responder este chat por ${cfg.PAUSA_HORAS}h (renova a cada mensagem da atendente).`);
return [{ json: { texto: linhas.join('\n') } }];

// Monta o contexto do modelo: id da conversa, data/hora de agora e calendário (função pura, sem rede)
const A = $('5.1 Definir id da conversa').first().json;
const cfg = $('CONFIG').first().json;
const instr = $('INSTRUCOES').first().json;

const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const pad = (n) => String(n).padStart(2, '0');

// Tudo é calculado em função de "agora" (Date) e do fuso da CONFIG, nunca do fuso do container
function montarContexto(agora, item, config, instrucoes) {
  const tz = config.TIMEZONE || 'America/Sao_Paulo';
  const partes = {};
  new Intl.DateTimeFormat('en-US', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(agora).forEach((p) => { partes[p.type] = p.value; });
  const ano = Number(partes.year);
  const mes = Number(partes.month);
  const dia = Number(partes.day);

  // dia da semana de uma data (só Y-M-D), via UTC: sem depender de fuso nem de horário de verão
  const hoje = Date.UTC(ano, mes - 1, dia);
  const agoraTxt = `AGORA: ${DIAS[new Date(hoje).getUTCDay()]}, ${pad(dia)}/${pad(mes)}/${ano}, ${partes.hour}:${partes.minute} (horário de Brasília)`;

  const feriados = new Set(String(instrucoes.FERIADOS ?? '').split(',').map((s) => s.trim()).filter(Boolean));
  const total = Math.max(1, Math.floor(Number(config.DIAS_CALENDARIO) || 1));
  const linhas = [];
  for (let i = 0; i < total; i++) {
    const d = new Date(hoje + i * 86400000); // soma de dias na data pura (UTC), sem DST
    const iso = d.toISOString().slice(0, 10);
    const dow = d.getUTCDay();
    const feriado = feriados.has(iso);
    const fimDeSemana = feriado || dow === 5 || dow === 6 || dow === 0;
    const preco = fimDeSemana ? 'sexta-a-domingo/feriado (weekendPrice)' : 'segunda-a-quinta (weekdayPrice)';
    const horario = (feriado || dow === 0) ? 'domingos e feriados (sundays_holidays)' : 'segunda-a-sábado (weekdays)';
    linhas.push(`${iso} ${DIAS[dow]}${feriado ? ' | FERIADO' : ''} | preço: ${preco} | horário: ${horario}`);
  }

  const mensagemSistema = instrucoes.PERSONA_E_REGRAS
    + '\n\nFATOS DO PARQUE\n' + instrucoes.FATOS_DO_PARQUE
    + '\n\nAVISOS DE HOJE\n' + (instrucoes.AVISOS_DE_HOJE || '(nenhum)')
    + '\n\n' + agoraTxt
    + '\n\nCALENDÁRIO\n' + linhas.join('\n');

  return Object.assign({}, item, {
    sessionKey: `${item.chatId}:${item.conversaId}`,
    textoCliente: item.texto,
    mensagemSistema,
  });
}

return [{ json: montarContexto(new Date(), A, cfg, instr) }];
